CREATE TABLE IF NOT EXISTS trusted_authority_keys (key_id TEXT PRIMARY KEY, principal_id TEXT NOT NULL, algorithm TEXT NOT NULL CHECK(algorithm='Ed25519'), public_key_pem TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_facts (seq INTEGER PRIMARY KEY AUTOINCREMENT, fact_type TEXT NOT NULL, subject_id TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS policy_redemptions (authorization_id TEXT PRIMARY KEY REFERENCES policy_authorizations(id), continuation_id TEXT NOT NULL UNIQUE REFERENCES continuation_acceptances(id), redeemed_at TEXT NOT NULL);
ALTER TABLE work_items ADD COLUMN authorization TEXT NOT NULL DEFAULT 'both';
